from collections import deque
def solve(I):
    I=np.array(I); H,W=I.shape
    A=[(r,c) for r in range(H) for c in range(W) if I[r,c]==1]
    o=I.copy()
    def line_cells(r):  # horizontal segments between same-row anchors
        return [(r,c) for a,b in zip(A,A[1:]) if a[0]==b[0] and a[1]<=c<=b[1]][:1] or [None]
    hseg=[]; vseg=[]
    from itertools import combinations
    ar={a for a,_ in A}; ac={b for _,b in A}
    for p,q in combinations(A,2):
        if p[0]==q[0]:
            hseg.append(p)
        if p[1]==q[1]:
            vseg.append(p)
    segs=[]
    for p in hseg:
        q_=next(q_ for qq,q_ in combinations(A,2) if qq[0]==p[0] and qq!=p and abs(q_[1]-p[1])>1) if False else None
    # simpler: group by row / col
    for r in sorted(ar):
        cs=sorted(c for rr,c in A if rr==r)
        for a,b in zip(cs,cs[1:]):
            for c in range(a,b+1): segs.append((r,c))
    for c in sorted(ac):
        rs=sorted(rr for rr,cc in A if cc==c)
        for a,b in zip(rs,rs[1:]):
            for r in range(a,b+1): segs.append((r,c))
    L=[[I[i,j]!=0 for i,j in segs] if False else set(segs)]
    segset=set(segs)
    seen=np.zeros_like(I,bool)
    for r in range(H):
        for c in range(W):
            if I[r,c]==2 and not seen[r,c]:
                q=deque([(r,c)]); seen[r,c]=True; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            rr,cc=a+dr,b+dc
                            if 0<=rr<H and 0<=cc<W and not seen[rr,cc] and I[rr,cc]==2:
                                seen[rr,cc]=True; q.append((rr,cc))
                if any((rr,cc) in segset for rr,cc in cells):
                    for rr,cc in cells: o[rr,cc]=1
    return o.tolist()
